<?php
require_once __DIR__.'/includes/functions.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=db()->prepare('SELECT b.*,c.name AS category_name FROM books b LEFT JOIN categories c ON c.id=b.category_id WHERE b.id=? AND b.is_active=1');$s->execute([$id?:0]);$book=$s->fetch();if(!$book){http_response_code(404);$pageTitle='Book not found';require __DIR__.'/includes/header.php';echo '<div class="empty-state"><i class="bi bi-book d-block mb-3"></i><h1 class="h3">Book not found</h1><a href="catalog.php">Return to catalog</a></div>';require __DIR__.'/includes/footer.php';exit;}
$pageTitle=$book['title'];require __DIR__.'/includes/header.php';
?>
<div class="mb-3"><a href="catalog.php" class="text-decoration-none"><i class="bi bi-arrow-left me-1"></i> Back to catalog</a></div><div class="surface p-3 p-md-5"><div class="row g-4 g-lg-5"><div class="col-md-4"><img class="detail-cover" src="<?=e(cover_url($book['cover_image']))?>" alt="<?=e($book['title'])?> cover"></div><div class="col-md-8"><span class="badge-soft"><?=e($book['category_name']??'General')?></span><h1 class="display-6 fw-bold mt-3"><?=e($book['title'])?></h1><p class="fs-5 muted">by <?=e($book['author'])?></p><span class="<?= $book['available_quantity']>0?'badge-available':'badge-unavailable' ?> badge-soft"><?= $book['available_quantity']>0?(int)$book['available_quantity'].' copies available':'Currently unavailable' ?></span><p class="mt-4" style="line-height:1.8"><?=nl2br(e($book['description']?:'No description has been added for this title yet.'))?></p><div class="row g-3 mt-2"><?php foreach(['ISBN'=>'isbn','Publisher'=>'publisher','Publication year'=>'publication_year','Total copies'=>'total_quantity'] as $label=>$field): ?><div class="col-6"><div class="small muted"><?=e($label)?></div><strong><?=e((string)($book[$field]?:'Not provided'))?></strong></div><?php endforeach; ?></div><div class="d-flex flex-wrap gap-2 mt-4"><?php if(current_user() && current_user()['role']==='student'): ?><form method="post" action="reservations.php"><?=csrf_field()?><input type="hidden" name="book_id" value="<?=(int)$book['id']?>"><button class="btn btn-primary" type="submit" name="action" value="reserve" > <i class="bi bi-bookmark-plus me-1"></i> Request / reserve</button></form><?php elseif(!current_user()): ?><a class="btn btn-primary" href="login.php">Log in to reserve</a><?php endif; ?><a class="btn btn-outline-primary" href="catalog.php">Explore more books</a></div></div></div></div>
